// The source from which to copy/move. This can either be a folder (when
// copying/moving messages from one folder to another), or a file (when e.g.
// saving a message draft or storing a copy of a sent message to the "Sent"
// folder).
mozilla::Maybe<RefPtr<nsIMsgFolder>> mSrcFolder;
mozilla::Maybe<RefPtr<nsIFile>> mSrcFile;

// The Exchange client and folder ID to use when creating the message item on
// the remote server.
nsCString mDstFolderId;
RefPtr<IExchangeClient> mClient;

// The listener to inform of the status of the copy/move operation.
RefPtr<nsIMsgCopyServiceListener> mCopyServiceListener;

// The index into `mHeaders` of the message currently being copied/move.
size_t mCurIndex;

// A buffer containing the full message content.
//
// This isn't great; ideally we'd stream the message to the client as it's
// provided to `CopyData()`, but the current architecture of the Exchange code
// does not allow this because we require the whole message to be available
// before we can serialize it.
nsCString mBuffer;

if (mSrcFolder) {
  // Identify the relevant message service for the message we want to copy,
  // and ask it to stream the message's content to us.
  nsCString uri;
  MOZ_TRY(mSrcFolder.value()->GetUriForMsg(mHeaders[mCurIndex], uri));

  nsCOMPtr<nsIMsgMessageService> messageService;
  MOZ_TRY(GetMessageServiceFromURI(uri, getter_AddRefs(messageService)));

  // Wrap the current handler in a `CopyMessageStreamListener` so that
  // `nsIMsgMessageService::CopyMessage()` can use it as an
  // `nsIStreamListener`.
  RefPtr<CopyMessageStreamListener> copyListener =
      new CopyMessageStreamListener(this, mIsMove);

  // We'll buffer up the message in mBuffer before we proceed, see
  // BeginCopy()/CopyData()/EndCopy().
  return messageService->CopyMessage(uri, copyListener, mIsMove, nullptr,
                                     mWindow);

mCurIndex++;
if (mCurIndex == mHeaders.Length()) {
  // We've reached the end of our queue.
  return OnCopyCompleted(NS_OK);
}

return StartCopyingNextMessage();

if (isSameServer) {
  // Since the folders are on the same (Exchange) server, the other folder
  // must also be an Exchange Folder.
  nsCOMPtr<IExchangeFolder> exchangeSourceFolder{
      do_QueryInterface(aSrcFolder, &rv)};
  NS_ENSURE_SUCCESS(rv, rv);
  const auto undoType =
      aIsMove ? nsIMessenger::eMoveMsg : nsIMessenger::eCopyMsg;
  rv = CopyItemsOnSameServer(exchangeSourceFolder, aSrcHdrs, aIsMove,
                             aMsgWindow, aCopyListener, aAllowUndo, undoType,
                             nullptr);
  NS_ENSURE_SUCCESS(rv, rv);
} else {
  // Cross-server copy or move. Instantiate a `ExchangeMessageCopyHandler` for
  // this operation.
  nsCString exchangeId;
  nsresult rv = GetExchangeId(exchangeId);
  NS_ENSURE_SUCCESS(rv, rv);

  nsCOMPtr<IExchangeClient> client;
  MOZ_TRY(GetProtocolClient(getter_AddRefs(client)));

  RefPtr<ExchangeMessageCopyHandler> handler = new ExchangeMessageCopyHandler(
      aSrcFolder, this, aSrcHdrs, aIsMove, aMsgWindow, exchangeId, client,
      aCopyListener);
